// Shared per-spec data setup. Each spec's beforeEach RESETS then SEEDS via the app's /__test__
// endpoint — this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
// silent failure would surface later as confusing, misattributed assertion failures on unrelated
// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
// the break is attributed to the seed contract, and so a developer running its own spec sees the
// broken endpoint immediately instead of shipping it.
import { request, type APIResponse } from '@playwright/test';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;

async function must(res: Promise<APIResponse>, what: string): Promise<void> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

// Usage in a spec:
//   test.beforeEach(async () => { await resetAndSeed({ /* rows this spec needs */ }); });
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.invoice.InvoiceRequest;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
 * ARRANGE data; they ASSERT only through the UI.
 */
@Profile("e2e")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private final Audit audit;
    private final JdbcTemplate jdbc;

    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
        this.audit = audit;
        this.jdbc = jdbc;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    @Transactional
    public void reset() {
        audit.clear();
        // Children first; H2 refuses to TRUNCATE a table referenced by a foreign key, so disable
        // referential checks for the duration of the truncates.
        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
        try {
            jdbc.execute("TRUNCATE TABLE project_tag");
            jdbc.execute("TRUNCATE TABLE tag RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE invoice_line_item RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
            jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
        } finally {
            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
        }
    }

    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
    @PostMapping("/seed")
    @Transactional
    public void seed(@RequestBody Map<String, Object> fixture) {
        for (Map<String, Object> c : rows(fixture, "clients")) {
            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
        }
        for (Map<String, Object> c : rows(fixture, "contacts")) {
            jdbc.update("INSERT INTO contact (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
                    ((Number) c.get("id")).longValue(), ((Number) c.get("clientId")).longValue(),
                    c.get("name"), c.get("email"), c.get("role"));
        }
        for (Map<String, Object> p : rows(fixture, "projects")) {
            jdbc.update("INSERT INTO project (id, name, client_id) VALUES (?, ?, ?)",
                    ((Number) p.get("id")).longValue(), p.get("name"),
                    ((Number) p.get("clientId")).longValue());
        }
        for (Map<String, Object> t : rows(fixture, "tags")) {
            jdbc.update("INSERT INTO tag (id, name) VALUES (?, ?)",
                    ((Number) t.get("id")).longValue(), t.get("name"));
        }
        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
                    ((Number) pt.get("projectId")).longValue(), ((Number) pt.get("tagId")).longValue());
        }
        for (Map<String, Object> t : rows(fixture, "tasks")) {
            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
                    ((Number) t.get("id")).longValue(), ((Number) t.get("projectId")).longValue(),
                    t.get("title"), Boolean.TRUE.equals(t.get("done")));
        }
        for (Map<String, Object> i : rows(fixture, "invoices")) {
            LocalDate issued = i.get("issuedDate") == null ? LocalDate.now()
                    : LocalDate.parse(i.get("issuedDate").toString());
            LocalDate due = i.get("dueDate") == null ? issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS)
                    : LocalDate.parse(i.get("dueDate").toString());
            long invoiceId = ((Number) i.get("id")).longValue();
            List<Map<String, Object>> lineItems = rows(i, "lineItems");
            // An invoice is the sum of its line items; a fixture giving only an amount describes an
            // invoice raised as one figure, which is carried as a single line.
            if (lineItems.isEmpty() && i.get("amount") != null) {
                lineItems = List.of(Map.of("description", InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION,
                        "qty", 1, "unitPrice", i.get("amount")));
            }
            BigDecimal amount = BigDecimal.ZERO;
            for (Map<String, Object> l : lineItems) {
                amount = amount.add(new BigDecimal(l.get("qty").toString())
                        .multiply(new BigDecimal(l.get("unitPrice").toString())));
            }
            jdbc.update("INSERT INTO invoice (id, project_id, amount, status, issued_date, due_date)"
                    + " VALUES (?, ?, ?, ?, ?, ?)",
                    invoiceId, ((Number) i.get("projectId")).longValue(),
                    amount.setScale(2, RoundingMode.HALF_UP),
                    seedStatus(i.get("status")), issued, due);
            for (Map<String, Object> l : lineItems) {
                if (l.get("id") != null) {
                    jdbc.update("INSERT INTO invoice_line_item (id, invoice_id, description, qty, unit_price)"
                            + " VALUES (?, ?, ?, ?, ?)",
                            ((Number) l.get("id")).longValue(), invoiceId, l.get("description"),
                            new BigDecimal(l.get("qty").toString()), new BigDecimal(l.get("unitPrice").toString()));
                } else {
                    jdbc.update("INSERT INTO invoice_line_item (invoice_id, description, qty, unit_price)"
                            + " VALUES (?, ?, ?, ?)",
                            invoiceId, l.get("description"),
                            new BigDecimal(l.get("qty").toString()), new BigDecimal(l.get("unitPrice").toString()));
                }
            }
        }
        // Continue generated ids after the explicitly seeded ones.
        restartIdentity("client");
        restartIdentity("contact");
        restartIdentity("project");
        restartIdentity("invoice");
        restartIdentity("invoice_line_item");
        restartIdentity("task");
        restartIdentity("tag");
    }

    /**
     * Invoices without a status are seeded as new drafts. Older fixtures may describe an
     * issued-but-unpaid invoice as "UNPAID"; this domain models that state as SENT.
     */
    private static String seedStatus(Object status) {
        if (status == null) {
            return InvoiceStatus.DRAFT.name();
        }
        if ("UNPAID".equals(status)) {
            return InvoiceStatus.SENT.name();
        }
        return status.toString();
    }

    private void restartIdentity(String table) {
        Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
        Object value = fixture.get(key);
        return value == null ? List.of() : (List<Map<String, Object>>) value;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.task;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The task list kept for a project. */
@RestController
@RequestMapping("/api/projects/{projectId}/tasks")
public class TaskController {

    private final TaskService service;

    public TaskController(TaskService service) {
        this.service = service;
    }

    @GetMapping
    public List<TaskResponse> list(@PathVariable Long projectId) {
        return service.listForProject(projectId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public TaskResponse create(@PathVariable Long projectId, @Valid @RequestBody TaskRequest request) {
        return service.create(projectId, request);
    }

    @PostMapping("/{taskId}/toggle")
    public TaskResponse toggle(@PathVariable Long projectId, @PathVariable Long taskId) {
        return service.toggle(projectId, taskId);
    }
}
package net.officefloor.hq.app.task;

import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import net.officefloor.hq.app.project.Project;

/** A to-do item on a project's task list, ticked off once done. */
@Entity
@Table(name = "task")
public class Task {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    private String title;

    private boolean done;

    protected Task() {
    }

    public Task(Project project, String title) {
        this.project = project;
        this.title = title;
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    public String getTitle() {
        return title;
    }

    public boolean isDone() {
        return done;
    }

    /** Flips the task between open and done. */
    public void toggle() {
        this.done = !this.done;
    }
}
package net.officefloor.hq.app.task;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface TaskRepository extends JpaRepository<Task, Long> {

    /** A project's tasks in the order they were added. */
    List<Task> findByProjectIdOrderById(Long projectId);

    Optional<Task> findByIdAndProjectId(Long id, Long projectId);
}
package net.officefloor.hq.app.task;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/** Payload to add a task to a project. */
public record TaskRequest(@NotBlank @Size(max = 255) String title) {
}
package net.officefloor.hq.app.task;

public record TaskResponse(Long id, Long projectId, String title, boolean done) {

    static TaskResponse from(Task task) {
        return new TaskResponse(task.getId(), task.getProject().getId(), task.getTitle(), task.isDone());
    }
}
package net.officefloor.hq.app.task;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class TaskService {

    private final TaskRepository tasks;
    private final ProjectRepository projects;
    private final Audit audit;

    public TaskService(TaskRepository tasks, ProjectRepository projects, Audit audit) {
        this.tasks = tasks;
        this.projects = projects;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<TaskResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project");
        }
        return tasks.findByProjectIdOrderById(projectId).stream().map(TaskResponse::from).toList();
    }

    @Transactional
    public TaskResponse create(Long projectId, TaskRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        Task saved = tasks.save(new Task(project, request.title().trim()));
        return TaskResponse.from(saved);
    }

    /** Ticks a task off (or reopens it) and records the change in the audit log. */
    @Transactional
    public TaskResponse toggle(Long projectId, Long taskId) {
        Task task = tasks.findByIdAndProjectId(taskId, projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown task"));
        task.toggle();
        audit.record("TASK_TOGGLED id=" + task.getId() + " done=" + task.isDone());
        return TaskResponse.from(task);
    }
}
CREATE TABLE task (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT       NOT NULL,
    title      VARCHAR(255) NOT NULL,
    done       BOOLEAN      NOT NULL DEFAULT FALSE,
    CONSTRAINT task_project_fk FOREIGN KEY (project_id) REFERENCES project (id)
);

CREATE INDEX task_project_idx ON task (project_id);
-- Projects can be labelled with tags so they can be grouped. A tag is a shared label; a project
-- carries any number of them. Tagging belongs to the project and goes with it if it is deleted.
CREATE TABLE tag (
    id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    CONSTRAINT tag_name_uq UNIQUE (name)
);

CREATE TABLE project_tag (
    project_id BIGINT NOT NULL,
    tag_id     BIGINT NOT NULL,
    CONSTRAINT project_tag_pk PRIMARY KEY (project_id, tag_id),
    CONSTRAINT project_tag_project_fk FOREIGN KEY (project_id) REFERENCES project (id) ON DELETE CASCADE,
    CONSTRAINT project_tag_tag_fk FOREIGN KEY (tag_id) REFERENCES tag (id) ON DELETE CASCADE
);

CREATE INDEX project_tag_tag_idx ON project_tag (tag_id);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema (base has no domain migrations). JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

