package net.officefloor.hq.app.task;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class TaskService {

    private final TaskRepository tasks;
    private final ProjectRepository projects;
    private final Audit audit;

    public TaskService(TaskRepository tasks, ProjectRepository projects, Audit audit) {
        this.tasks = tasks;
        this.projects = projects;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<TaskResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project");
        }
        return tasks.findByProjectIdOrderById(projectId).stream().map(TaskResponse::from).toList();
    }

    @Transactional
    public TaskResponse create(Long projectId, TaskRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        Task saved = tasks.save(new Task(project, request.title().trim()));
        return TaskResponse.from(saved);
    }

    /** Ticks a task off (or reopens it) and records the change in the audit log. */
    @Transactional
    public TaskResponse toggle(Long projectId, Long taskId) {
        Task task = tasks.findByIdAndProjectId(taskId, projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown task"));
        task.toggle();
        audit.record("TASK_TOGGLED id=" + task.getId() + " done=" + task.isDone());
        return TaskResponse.from(task);
    }
}
CREATE TABLE task (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT       NOT NULL,
    title      VARCHAR(255) NOT NULL,
    done       BOOLEAN      NOT NULL DEFAULT FALSE,
    CONSTRAINT task_project_fk FOREIGN KEY (project_id) REFERENCES project (id)
);

CREATE INDEX task_project_idx ON task (project_id);
-- Projects can be labelled with tags so they can be grouped. A tag is a shared label; a project
-- carries any number of them. Tagging belongs to the project and goes with it if it is deleted.
CREATE TABLE tag (
    id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    CONSTRAINT tag_name_uq UNIQUE (name)
);

CREATE TABLE project_tag (
    project_id BIGINT NOT NULL,
    tag_id     BIGINT NOT NULL,
    CONSTRAINT project_tag_pk PRIMARY KEY (project_id, tag_id),
    CONSTRAINT project_tag_project_fk FOREIGN KEY (project_id) REFERENCES project (id) ON DELETE CASCADE,
    CONSTRAINT project_tag_tag_fk FOREIGN KEY (tag_id) REFERENCES tag (id) ON DELETE CASCADE
);

CREATE INDEX project_tag_tag_idx ON project_tag (tag_id);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema (base has no domain migrations). JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

